def countBowlSubarrays(nums):
    n = len(nums)
    stack = []  # indices, values strictly decreasing
    pairs = 0
    for r in range(n):
        while stack and nums[stack[-1]] < nums[r]:
            stack.pop()
            pairs += 1
        if stack:
            pairs += 1
        stack.append(r)
    # every adjacent pair was counted once, but a bowl needs length >= 3
    return pairs - (n - 1)
